bool VersionHistory::validateJsonForCreation(const Json::Value &pJson, std::string &err)
{
    if(pJson.isMember("id"))
    {
        if(!validJsonOfField(0, "id", pJson["id"], err, true))
            return false;
    }
    if(pJson.isMember("content_id"))
    {
        if(!validJsonOfField(1, "content_id", pJson["content_id"], err, true))
            return false;
    }
    if(pJson.isMember("version_note"))
    {
        if(!validJsonOfField(2, "version_note", pJson["version_note"], err, true))
            return false;
    }
    if(pJson.isMember("date_saved"))
    {
        if(!validJsonOfField(3, "date_saved", pJson["date_saved"], err, true))
            return false;
    }
    else
    {
        err="The date_saved column cannot be null";
        return false;
    }
    if(pJson.isMember("editor_user_id"))
    {
        if(!validJsonOfField(4, "editor_user_id", pJson["editor_user_id"], err, true))
            return false;
    }
    if(pJson.isMember("character_count"))
    {
        if(!validJsonOfField(5, "character_count", pJson["character_count"], err, true))
            return false;
    }
    if(pJson.isMember("sha1_hash"))
    {
        if(!validJsonOfField(6, "sha1_hash", pJson["sha1_hash"], err, true))
            return false;
    }
    if(pJson.isMember("version_data"))
    {
        if(!validJsonOfField(7, "version_data", pJson["version_data"], err, true))
            return false;
    }
    else
    {
        err="The version_data column cannot be null";
        return false;
    }
    if(pJson.isMember("keep_forever"))
    {
        if(!validJsonOfField(8, "keep_forever", pJson["keep_forever"], err, true))
            return false;
    }
    if(pJson.isMember("is_current"))
    {
        if(!validJsonOfField(9, "is_current", pJson["is_current"], err, true))
            return false;
    }
    if(pJson.isMember("is_legacy"))
    {
        if(!validJsonOfField(10, "is_legacy", pJson["is_legacy"], err, true))
            return false;
    }
    return true;
}
